package dev.astralreach.hytale;
import com.hypixel.hytale.component.*;import com.hypixel.hytale.protocol.packets.interface_.*;import com.hypixel.hytale.server.core.entity.entities.Player;import com.hypixel.hytale.server.core.entity.entities.player.pages.InteractiveCustomUIPage;import com.hypixel.hytale.server.core.ui.builder.*;import com.hypixel.hytale.server.core.universe.PlayerRef;import com.hypixel.hytale.server.core.universe.world.storage.EntityStore;
/** Read-only chapters; native bench recipes retain all crafting authority. */
final class GuidePage extends InteractiveCustomUIPage<StationPage.Action>{
 private record Step(String title,String body,String icon,String second){}
 private record Chapter(String tab,String title,String intro,Step[] steps,String icon,String next,String note){}
 private static final Chapter[]CHAPTERS={
  new Chapter("First steps","From rock to rocket","Gather, process and assemble on Orbis before your first flight. Every part of this route is obtainable on your home world.",new Step[]{new Step("Gather nickel and oil shale","Mine home-world nickel underground and oil shale in deposits. Bring iron, copper and gathered fuel for processing.","AR_NickelOre","AR_OilShale"),new Step("Refine materials and propellant","Smelt nickel in the Orbital Smelter. Press frame plates, refine oil shale, then fill cells at the Propellant Conditioner.","AR_FramePlate","AR_PropellantCell"),new Step("Prepare your launch site","Form the platform and supply a selected rocket. Before boarding, equip a complete suit and carry filled oxygen.","AR_LaunchPadModule","AR_SuitWorkbench")},"AR_ComponentPress","Start with the Orbital Smelter and Component Press.","The Assembly Bench supplies your first machines and components."),
  new Chapter("Launch site","Build a proper launch site","Your launch console remembers its blueprint and supplied parts. Construction uses the standing rocket size shown in the catalogue.",new Step[]{new Step("Form a 25 ×25 platform","Place 25 Launch Pad Modules in a 5 ×5 grid on level ground. The finished platform is 25 ×25 blocks.","AR_LaunchPadModule","AR_LaunchDeck"),new Step("Place the separate control","Place the Launch Console 14 blocks from centre, facing the pad. Select a rocket to see its ghost and parts list.","AR_LaunchConsole","AR_FramePlate"),new Step("Supply and assemble","Supply carried parts in Adventure or use Supply in Creative. Construction starts when fully supplied and clear.","AR_PressureHullPart","AR_OrbitalEnginePart")},"AR_LaunchConsole","Return to this console to build or open Flight Control.","Make room before changing a blueprint to refund paid parts."),
  new Chapter("Rockets","Choose, fuel and fly","Five large rockets currently share the paid Lune route. Later releases will expand mission ranges and progression.",new Step[]{new Step("Choose your spacecraft","Compare the five rockets in the catalogue. Each card shows its height, footprint and required parts.","AR_Soyuz","AR_KestrelStack"),new Step("Protect the round trip","Supply 9,000 units:6,000 outward and 3,000 reserved for home. Lost Survey completion reduces future fuel use by 5%.","AR_PropellantCell","AR_EmptyFuelCell"),new Step("Board and reach space","Launch from Flight Control. Watch ascent and separation before selecting a destination. /astral-map reopens navigation.","AR_FlightComputer","AR_ThermalShield")},"AR_LaunchConsole","Returned assemblies reduce your next construction bill.","Rebuild expendable stages. Your paid return stays protected."),
  new Chapter("Suits & oxygen","Stay alive beyond Orbis","A complete four-piece suit seals your body. A helmet alone shows the oxygen HUD but does not make an unsealed suit safe.",new Step[]{new Step("Craft and upgrade your suit","Craft all four Survey pieces at the Suit Workbench. Use its tabs for higher mission tiers and other equipment.","AR_SuitWorkbench","AR_EmptyOxygenCanister"),new Step("Fill reusable canisters","Fill reusable canisters at the Oxygen Collector on Orbis using gathered fuel. A full standard tank lasts 20 minutes at rest.","AR_OxygenCollector","AR_OxygenCanister"),new Step("Make a breathable field","A powered diffuser supplies an eight-block sphere. Load filled canisters; upkeep and nearby people use its oxygen.","AR_OxygenDiffuser","AR_StationLifeSupport")},"AR_EmptyLargeOxygenCanister","The life-support expedition unlocks a 40-minute tank recipe.","Learn the recipe, then craft and fill your larger tank."),
  new Chapter("Lune","Explore an airless world","Lune has crater fields, dunes, scattered rocks and underground lava tubes. Lower gravity helps you jump; your suit carries every breath.",new Step[]{new Step("Land with your upper stage","Your ship descends to a saved berth. Use the control beside its landed stage to board for the prepaid return.","AR_ReturnBeacon","AR_LuneRegolith"),new Step("Prepare for exploration","Bring spare oxygen and electric lighting. Torches need an oxygen field. Bootprints mark your trail on loose regolith.","AR_OxygenCanister","AR_BeaconCell"),new Step("Bring home lunar resources","Mine titanium and aluminium. Explore skylights and lava tubes carefully: there is no breathable air underground.","AR_RawTitanium","AR_RawAluminium")},"AR_FieldReceiver","Take a Field Receiver before a longer expedition.","It tracks sites and invited rescue beacons without giving free travel."),
  new Chapter("Stations","Build your home in orbit","Each player can own one Orbis station and invite visitors. Ships dock at separate airlocks along a protected concourse.",new Step[]{new Step("Bring a Station Core","Reach orbit with your paid ship and a crafted Station Core. Select Orbis stations to establish a personal station.","AR_StationCore","AR_StationDeck"),new Step("Dock through your own airlock","Nine airlocks sit outside the building plot. Ships approach nose-first and stay at their individual reserved ports.","AR_StationAirlock","AR_StationConcourse"),new Step("Expand from starter platforms","Build habitats behind the concourse, starting from small platforms. Add life support and invite visitors through the controls.","AR_StationLifeSupport","AR_StationBattery")},"AR_StationTracker","Watch station passes from Orbis with a Station Tracker.","Board your docked ship to release and return to destinations."),
  new Chapter("Rescue & surveys","Adventure with lasting rewards","The Field Receiver combines invited rescue signals and expedition journals. Rewards are earned through real exploration.",new Step[]{new Step("Prepare a rescue beacon","Place a beacon, load a Beacon Cell and invite rescuers. A cell lasts 30 minutes; its clock continues when stopped.","AR_RescueBeacon","AR_BeaconCell"),new Step("Recover the lost survey","Inspect the relay, follow the route and recover both archives. One complete shelter grants a permanent 5% fuel saving.","AR_DamagedRelay","AR_ResearchArchive"),new Step("Unlock useful equipment","Life-support records unlock the larger tank recipe. Mobility records unlock the rover. Recover both records at one site.","AR_EmptyLargeOxygenCanister","AR_LunarRover")},"AR_FieldReceiver","Recipes remain learned after you return home.","Craft unlocked equipment using your gathered materials."),
 };
 private int chapter;
 GuidePage(PlayerRef p){super(p,CustomPageLifetime.CanDismiss,StationPage.Action.CODEC);}
 static void open(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p){var player=s.getComponent(r,Player.getComponentType());if(player!=null)player.getPageManager().openCustomPage(r,s,new GuidePage(p));}
 private void labels(UICommandBuilder c){var ch=CHAPTERS[chapter];c.set("#Title.Text",ch.title());c.set("#Intro.Text",ch.intro());for(int i=0;i<7;i++)c.set("#Selected"+i+".Visible",i==chapter);for(int i=0;i<3;i++){var row=ch.steps()[i];c.set("#StepTitle"+i+".Text",row.title());c.set("#StepBody"+i+".Text",row.body());c.set("#StepIcon"+i+".ItemId",row.icon());c.set("#StepSecond"+i+".ItemId",row.second());}c.set("#NextIcon.ItemId",ch.icon());c.set("#Next.Text",ch.next());c.set("#Note.Text",ch.note());}
 @Override public void build(Ref<EntityStore>r,UICommandBuilder c,UIEventBuilder e,Store<EntityStore>s){c.append("Pages/AstralReach/GuideTablet.ui");labels(c);for(int i=0;i<7;i++)e.addEventBinding(CustomUIEventBindingType.Activating,"#Chapter"+i,EventData.of("Action","Chapter"+i),false);e.addEventBinding(CustomUIEventBindingType.Activating,"#Close",EventData.of("Action","Close"),false);LunarEnvironment.interior(s,r,playerRef,"AR_tablet_open");}
 @Override public void handleDataEvent(Ref<EntityStore>r,Store<EntityStore>s,StationPage.Action e){s.getExternalData().getWorld().execute(()->{if(!r.isValid()||r.getStore()!=s)return;var player=s.getComponent(r,Player.getComponentType());if(player==null||player.getPageManager().getCustomPage()!=this)return;if(e.action.equals("Close")){close();return;}if(e.action.matches("Chapter[0-6]")){chapter=Integer.parseInt(e.action.substring(7));var c=new UICommandBuilder();labels(c);sendUpdate(c,false);}});}
}
